window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5f5f0eb0ab167d0c"]={"versions": [{"id": "FIG-5f5f0eb0ab167d0c", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Darstellung des AUTOSAR-ECU-Konfigurationsmetamodells (ECUC Parameter Configuration) für das BSW-Modul <code>Xcp</code>. Das Diagramm definiert die hierarchische Containerstruktur der Moduldefinition <code>Xcp :EcucModuleDef</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell umfasst folgende Konfigurationselemente und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>Xcp :EcucModuleDef</code> (Multiplizität <code>0..1</code>): Wurzelmoduldefinition, aggregiert über die Komposition <code>+container</code> den Container <code>XcpConfig</code>.\n</li><li><code>XcpConfig :EcucParamConfContainerDef</code>: Hauptkonfigurationscontainer mit der Eigenschaft <code>multipleConfigurationContainer = true</code>. Aggregiert über Kompositionen (<code>+subContainer</code>) die folgenden Sub-Container:\n<ul class=\"fig-list\"><li><code>XcpPdu :EcucChoiceContainerDef</code> (Multiplizität <code>1..*</code>): Auswahlcontainer für XCP-PDUs.\n</li><li><code>XcpEventChannel :EcucParamConfContainerDef</code> (Multiplizität <code>1..*</code>): Definition der Ereigniskanäle.\n</li><li><code>XcpDaqList :EcucParamConfContainerDef</code> (Multiplizität <code>1..*</code>): Definition der DAQ-Listen.\n</li></ul>\n</li><li><code>XcpDaqList</code> aggregiert über <code>+subContainer</code> zwei weitere ParamConf-Container:\n<ul class=\"fig-list\"><li><code>XcpOdt :EcucParamConfContainerDef</code> (Multiplizität <code>1..*</code>): Konfiguration der Object Description Tables (ODT).\n</li><li><code>XcpDto :EcucParamConfContainerDef</code> (Multiplizität <code>0..*</code>): Konfiguration der Data Transfer Objects (DTO).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne dynamische Laufzeitsequenzen oder Verhaltensabläufe. Es legt die syntaktische Struktur und Schachtelungshierarchie für Konfigurationsgeneratoren und XML-Beschreibungsdateien fest.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Spezifikation der AUTOSAR-Modulkonfiguration für XCP:</p>\n<ul class=\"fig-list\"><li>Die Eigenschaft <code>multipleConfigurationContainer = true</code> an <code>XcpConfig</code> kennzeichnet diesen als Multi-Konfigurationscontainer für Post-Build-Varianten.\n</li><li>Es müssen mindestens eine PDU (<code>XcpPdu</code>), ein Ereigniskanal (<code>XcpEventChannel</code>) sowie eine DAQ-Liste (<code>XcpDaqList</code>) konfiguriert werden.\n</li><li>Jede DAQ-Liste muss mindestens einen ODT-Eintrag (<code>XcpOdt</code>, <code>1..*</code>) enthalten; DTO-Einträge (<code>XcpDto</code>, <code>0..*</code>) sind optional.\n</li></ul>"}, {"id": "FIG-099ce7073b76ec3f", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Darstellung des AUTOSAR-ECU-Konfigurationsmetamodells (ECUC Parameter Configuration) für das BSW-Modul <code>Xcp</code>. Das Diagramm definiert die hierarchische Containerstruktur der Moduldefinition <code>Xcp :EcucModuleDef</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell umfasst folgende Konfigurationselemente und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>Xcp :EcucModuleDef</code> (Multiplizität <code>0..1</code>): Wurzelmoduldefinition, aggregiert über die Komposition <code>+container</code> den Container <code>XcpConfig</code>.\n</li><li><code>XcpConfig :EcucParamConfContainerDef</code>: Hauptkonfigurationscontainer ohne Multi-Configuration-Attribut. Aggregiert über Kompositionen (<code>+subContainer</code>) die folgenden Sub-Container:\n<ul class=\"fig-list\"><li><code>XcpPdu :EcucChoiceContainerDef</code> (Multiplizität <code>1..*</code>): Auswahlcontainer für XCP-PDUs.\n</li><li><code>XcpEventChannel :EcucParamConfContainerDef</code> (Multiplizität <code>1..*</code>): Definition der Ereigniskanäle.\n</li><li><code>XcpDaqList :EcucParamConfContainerDef</code> (Multiplizität <code>1..*</code>): Definition der DAQ-Listen.\n</li></ul>\n</li><li><code>XcpDaqList</code> aggregiert über <code>+subContainer</code> zwei weitere ParamConf-Container:\n<ul class=\"fig-list\"><li><code>XcpOdt :EcucParamConfContainerDef</code> (Multiplizität <code>0..*</code>): Konfiguration der Object Description Tables (ODT).\n</li><li><code>XcpDto :EcucParamConfContainerDef</code> (Multiplizität <code>0..*</code>): Konfiguration der Data Transfer Objects (DTO).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne dynamische Laufzeitsequenzen oder Verhaltensabläufe. Es legt die syntaktische Struktur und Schachtelungshierarchie für Konfigurationsgeneratoren und XML-Beschreibungsdateien fest.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Spezifikation der AUTOSAR-Modulkonfiguration für XCP:</p>\n<ul class=\"fig-list\"><li><code>XcpConfig</code> besitzt keine Ausprägung als Multi-Konfigurationscontainer.\n</li><li>Es müssen mindestens eine PDU (<code>XcpPdu</code>), ein Ereigniskanal (<code>XcpEventChannel</code>) sowie eine DAQ-Liste (<code>XcpDaqList</code>) vorhanden sein.\n</li><li>Innerhalb einer konfigurierten DAQ-Liste (<code>XcpDaqList</code>) sind sowohl ODT-Einträge (<code>XcpOdt</code>, Multiplizität <code>0..*</code>) als auch DTO-Einträge (<code>XcpDto</code>, Multiplizität <code>0..*</code>) formal optional.\n</li></ul>"}], "trans": [{"from": "FIG-5f5f0eb0ab167d0c", "to": "FIG-099ce7073b76ec3f", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>XcpConfig</strong>: Das Attribut <code>multipleConfigurationContainer = true</code> wurde entfernt.\n</li><li><strong>XcpOdt</strong>: Die untere Multiplizität (<code>lowerMultiplicity</code>) wurde von <code>1</code> auf <code>0</code> geändert (Multiplizität neu <code>0..*</code> statt zuvor <code>1..*</code>).\n</li></ul>"}]};
